window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-729fbdfbafa9bce4"]={"versions": [{"id": "FIG-729fbdfbafa9bce4", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Komponentendiagramm (<code>cmp ArchitectureView-DeterministicClient</code>) zur Darstellung der Schnittstellenarchitektur auf System- und Prozessebene.\n</li><li><strong>Technischer Zweck:</strong> Spezifiziert die Interaktion zwischen einer deterministischen Adaptive Application und dem funktionalen Cluster <em>Execution Management</em> (<code>ara::exec</code>) der AUTOSAR Adaptive Platform (Release R18-03 / R1.4.0).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die Abstraktion des Prozesslebenszyklus sowie die Entkopplung von nicht-deterministischen Plattform- und OS-Ressourcen (Systemuhr, Host-Threading, OS-Zufallsgeneratoren), um reproduzierbare Berechnungen (z. B. für automatisierte Fahrfunktionen, Replay-Simulationen und SIL/HIL-Validierung) zu garantieren.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Komponenten (UML Components)</h5>\n<ul class=\"fig-list\"><li><strong><code>Application</code>:</strong> POSIX-basierter Prozess der Adaptive Application, welcher Algorithmen mit deterministischer Ausführungscharakteristik kapselt. Fungiert als Client gegenüber beiden Schnittstellen.\n</li><li><strong><code>Execution Management</code>:</strong> Zentraler Plattform-Daemon der Adaptive Platform (<code>ara::exec</code>), zuständig für Prozessüberwachung, deterministisches Scheduling und Lifecycle-Management. Stellt die korrespondierenden Ports bereit.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Klassen (Namespace <code>«ara::exec»</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>DeterministicClient</code> (<code>«ara::exec»</code>):</strong>\n<ul class=\"fig-list\"><li>Zugriffspunkt für deterministische Ausführungsmodelle.\n</li><li>Methoden:\n<ul class=\"fig-list\"><li><code>+ GetActivationTime()</code>: Liefert den deterministischen Zeitstempel des aktuellen Ausführungszyklus (unabhängig von der realen Host-Laufzeit).\n</li><li><code>+ GetNextActivationTime()</code>: Liefert den geplanten deterministischen Startzeitpunkt des Folgezyklus.\n</li><li><code>+ GetRandom()</code>: Liefert pseudo-zufällige Werte aus einem reproduzierbaren, durch das Execution Management synchronisierten PRNG-Zustand.\n</li><li><code>+ RunWorkerPool()</code>: Triggert die parallele Abarbeitung deterministischer Teilaufgaben über einen verwalteten Worker-Pool unter Vermeidung von Race Conditions.\n</li><li><code>+ WaitForNextActivation()</code>: Blockierender Synchronisationspunkt, der den Prozess bis zur nächsten deterministischen Zyklus-Freigabe suspendiert.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ApplicationClient</code> (<code>«ara::exec»</code>):</strong>\n<ul class=\"fig-list\"><li>Standard-Schnittstelle zur Lebenszyklus-Rückmeldung an das Execution Management.\n</li><li>Methoden:\n<ul class=\"fig-list\"><li><code>+ ReportApplicationState()</code>: Meldet interne Prozesszustände (z. B. <code>kRunning</code>, <code>kTerminating</code>).\n</li></ul>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Pfade</h5>\n<ul class=\"fig-list\"><li><strong>Provided / Required Ports:</strong>\n<ul class=\"fig-list\"><li><code>Application</code> nutzt (Required Interface / Socket) die Schnittstellen <code>DeterministicClient</code> und <code>ApplicationClient</code>.\n</li><li><code>Execution Management</code> implementiert und exponiert (Provided Interface / Ball) beide Ports via IPC.\n</li></ul>\n</li><li><strong>Kontrollpfad <code>Start / Terminate</code>:</strong>\n<ul class=\"fig-list\"><li>Gerichtete Kontrollbeziehung (gestrichelte Linie) vom <code>Execution Management</code> zur <code>Application</code>. Signalisiert die Erzeugung (POSIX <code>fork</code>/<code>exec</code>) und Terminierung (<code>SIGTERM</code>/<code>SIGKILL</code>) des Prozesses.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Prozessinitialisierung:</strong>\n<ul class=\"fig-list\"><li><code>Execution Management</code> startet die <code>Application</code> (<code>Start</code>).\n</li><li>Die Applikation initialisiert ihre Ressourcen und meldet über <code>ApplicationClient::ReportApplicationState(kRunning)</code> ihre Betriebsbereitschaft.\n</li></ul>\n</li><li><strong>Deterministische Regelschleife (Zyklische Abarbeitung):</strong>\n<ul class=\"fig-list\"><li>Die Applikation ruft blockierend <code>DeterministicClient::WaitForNextActivation()</code> auf.\n</li><li>Nach Trigger durch das <code>Execution Management</code> erwacht die Applikation im definierten Zyklus.\n</li><li>Abfrage der logischen Zykluszeit über <code>GetActivationTime()</code> und optional <code>GetNextActivationTime()</code>.\n</li><li>Bei Randomisierung Nutzung von <code>GetRandom()</code>; bei Datenparallelismus Ausführung über <code>RunWorkerPool()</code>.\n</li><li>Abschluss der Zyklusberechnung; Rücksprung zu <code>WaitForNextActivation()</code>.\n</li></ul>\n</li><li><strong>Prozessterminierung:</strong>\n<ul class=\"fig-list\"><li><code>Execution Management</code> initiiert den Shutdown (<code>Terminate</code>).\n</li><li>Die Applikation verlässt die Regelschleife, meldet <code>ReportApplicationState(kTerminating)</code> und gibt Ressourcen frei.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Verbot direkter POSIX-Aufrufe:</strong> Entwickler deterministischer Applikationen dürfen keine nicht-deterministischen OS-Primitives verwenden (<code>clock_gettime()</code>, <code>std::chrono::system_clock</code>, <code>std::thread</code>, <code>pthread_create</code>, <code>/dev/urandom</code>, <code>rand()</code>). Zeit, Threading und Zufall müssen ausnahmslos über den <code>DeterministicClient</code> bezogen werden.\n</li><li><strong>Run-to-Completion &amp; Barrieren:</strong> Berechnungen innerhalb eines Aktivierungszyklus müssen vor dem nächsten <code>WaitForNextActivation()</code> vollständig terminieren.\n</li><li><strong>Worker-Pool-Restriktionen:</strong> Parallelverarbeitung via <code>RunWorkerPool()</code> erfordert seiteneffektfreie Tasks, da das Framework die Reproduzierbarkeit der Abarbeitungsreihenfolge und Speicherzugriffe sicherstellt.\n</li><li><strong>Koexistenz:</strong> Die Implementierung von <code>DeterministicClient</code> entbindet nicht von der Pflicht, die Standard-Zustandsmeldungen über den <code>ApplicationClient</code> abzusetzen, um Watchdog-Timeouts und Alive-Supervision-Fehler durch das Execution Management zu verhindern.\n</li></ul>"}, {"id": "FIG-d96b0e2a2da5440d", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11", "R20-11", "R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Komponentendiagramm (<code>cmp ArchitectureView-DeterministicClient</code>) zur Darstellung der Schnittstellenarchitektur auf System- und Prozessebene.\n</li><li><strong>Technischer Zweck:</strong> Spezifiziert die Interaktion zwischen einer deterministischen Adaptive Application und dem funktionalen Cluster <em>Execution Management</em> (<code>ara::exec</code>) der AUTOSAR Adaptive Platform (Release R18-03 / R1.4.0).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die Abstraktion des Prozesslebenszyklus sowie die Entkopplung von nicht-deterministischen Plattform- und OS-Ressourcen (Systemuhr, Host-Threading, OS-Zufallsgeneratoren), um reproduzierbare Berechnungen (z. B. für automatisierte Fahrfunktionen, Replay-Simulationen und SIL/HIL-Validierung) zu garantieren.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Komponenten (UML Components)</h5>\n<ul class=\"fig-list\"><li><strong><code>Application</code>:</strong> POSIX-basierter Prozess der Adaptive Application, welcher Algorithmen mit deterministischer Ausführungscharakteristik kapselt. Fungiert als Client gegenüber beiden Schnittstellen.\n</li><li><strong><code>Execution Management</code>:</strong> Zentraler Plattform-Daemon der Adaptive Platform (<code>ara::exec</code>), zuständig für Prozessüberwachung, deterministisches Scheduling und Lifecycle-Management. Stellt die korrespondierenden Ports bereit.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Klassen (Namespace <code>«ara::exec»</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>DeterministicClient</code> (<code>«ara::exec»</code>):</strong>\n<ul class=\"fig-list\"><li>Zugriffspunkt für deterministische Ausführungsmodelle.\n</li><li>Methoden:\n<ul class=\"fig-list\"><li><code>+ GetActivationTime()</code>: Liefert den deterministischen Zeitstempel des aktuellen Ausführungszyklus (unabhängig von der realen Host-Laufzeit).\n</li><li><code>+ GetNextActivationTime()</code>: Liefert den geplanten deterministischen Startzeitpunkt des Folgezyklus.\n</li><li><code>+ GetRandom()</code>: Liefert pseudo-zufällige Werte aus einem reproduzierbaren, durch das Execution Management synchronisierten PRNG-Zustand.\n</li><li><code>+ RunWorkerPool()</code>: Triggert die parallele Abarbeitung deterministischer Teilaufgaben über einen verwalteten Worker-Pool unter Vermeidung von Race Conditions.\n</li><li><code>+ WaitForNextActivation()</code>: Blockierender Synchronisationspunkt, der den Prozess bis zur nächsten deterministischen Zyklus-Freigabe suspendiert.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ExecutionClient</code> (<code>«ara::exec»</code>):</strong>\n<ul class=\"fig-list\"><li>Standard-Schnittstelle zur Lebenszyklus-Rückmeldung an das Execution Management.\n</li><li>Methoden:\n<ul class=\"fig-list\"><li><code>+ ReportExecutionState()</code>: Meldet interne Prozesszustände (z. B. <code>kRunning</code>, <code>kTerminating</code>).\n</li></ul>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Pfade</h5>\n<ul class=\"fig-list\"><li><strong>Provided / Required Ports:</strong>\n<ul class=\"fig-list\"><li><code>Application</code> nutzt (Required Interface / Socket) die Schnittstellen <code>DeterministicClient</code> und <code>ExecutionClient</code>.\n</li><li><code>Execution Management</code> implementiert und exponiert (Provided Interface / Ball) beide Ports via IPC.\n</li></ul>\n</li><li><strong>Kontrollpfad <code>Start / Terminate</code>:</strong>\n<ul class=\"fig-list\"><li>Gerichtete Kontrollbeziehung (gestrichelte Linie) vom <code>Execution Management</code> zur <code>Application</code>. Signalisiert die Erzeugung (POSIX <code>fork</code>/<code>exec</code>) und Terminierung (<code>SIGTERM</code>/<code>SIGKILL</code>) des Prozesses.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Prozessinitialisierung:</strong>\n<ul class=\"fig-list\"><li><code>Execution Management</code> startet die <code>Application</code> (<code>Start</code>).\n</li><li>Die Applikation initialisiert ihre Ressourcen und meldet über <code>ExecutionClient::ReportExecutionState(kRunning)</code> ihre Betriebsbereitschaft.\n</li></ul>\n</li><li><strong>Deterministische Regelschleife (Zyklische Abarbeitung):</strong>\n<ul class=\"fig-list\"><li>Die Applikation ruft blockierend <code>DeterministicClient::WaitForNextActivation()</code> auf.\n</li><li>Nach Trigger durch das <code>Execution Management</code> erwacht die Applikation im definierten Ausführungszyklus (Aktivierungszeitpunkt).\n</li><li>Abfrage von deterministischer Zeit (<code>GetActivationTime()</code>, <code>GetNextActivationTime()</code>) und deterministischer Pseudozufallszahlen (<code>GetRandom()</code>).\n</li><li>Ggf. Abarbeitung paralleler Berechnungsaufgaben über <code>RunWorkerPool()</code>.\n</li></ul>\n</li><li><strong>Prozessterminierung:</strong>\n<ul class=\"fig-list\"><li><code>Execution Management</code> signalisiert der <code>Application</code> das Beenden (<code>Terminate</code>).\n</li><li>Die Applikation fährt kontrolliert herunter und meldet ihren Status über den <code>ExecutionClient</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Vorgaben:</strong>\n<ul class=\"fig-list\"><li>Deterministische Anwendungen müssen für das Lifecycle-Management zwingend <code>ara::exec::ExecutionClient</code> nutzen und ihren Zustand via <code>ReportExecutionState()</code> melden.\n</li><li>Für deterministisches Verhalten dürfen keine nicht-deterministischen OS-Dienste (wie Standard-Systemuhren, unkoordinierte POSIX-Threads oder systemweite Entropiequellen) genutzt werden; stattdessen ist strikt <code>ara::exec::DeterministicClient</code> zu verwenden.\n</li><li>Das Execution Management steuert den Prozessstart und die Terminierung (<code>Start / Terminate</code>) normativ über Plattform-Mechanismen.\n</li></ul>\n</li><li><strong>Entwickler-Hinweise:</strong>\n<ul class=\"fig-list\"><li><code>WaitForNextActivation()</code> blockiert den aufrufenden Thread bis zur Freigabe des nächsten Ausführungszyklus durch das Execution Management.\n</li><li>Bei Nutzung von <code>RunWorkerPool()</code> ist sicherzustellen, dass die Worker-Tasks frei von Daten-Races und unkontrollierten Synchronisationsprimitiven sind, um Replay-Fähigkeit zu gewährleisten.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-729fbdfbafa9bce4", "to": "FIG-d96b0e2a2da5440d", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Schnittstelle <code>ApplicationClient</code>:</strong> Ersetzt durch <code>ExecutionClient</code> (<code>«ara::exec»</code>).\n</li><li><strong>Methode <code>+ ReportApplicationState()</code>:</strong> Ersetzt durch <code>+ ReportExecutionState()</code> in <code>ExecutionClient</code>.\n</li><li><strong>Ports (Required/Provided):</strong> Port-Bezeichnungen zwischen <code>Application</code> und <code>Execution Management</code> von <code>ApplicationClient</code> auf <code>ExecutionClient</code> umbenannt.\n</li></ul>"}]};
